import unittest
from versions import supports
class Contract(unittest.TestCase):
    def test_boundaries(self):
        self.assertTrue(supports("1.0", "1.0", "2.0"))
        self.assertTrue(supports("2.0", "1.0", "2.0"))
    def test_numeric(self): self.assertTrue(supports("1.10", "1.9", "1.11"))
    def test_padding(self): self.assertTrue(supports("2", "2.0", "2.0.0"))
    def test_outside(self): self.assertFalse(supports("3", "1", "2"))
    def test_invalid(self):
        with self.assertRaises(ValueError): supports("1.x", "1", "2")

